77	// Normalize text for comparison (lowercase, remove punctuation, extra spaces)
78	function normalizeText(text: string): string {
79	  return text
80	    .toLowerCase()
81	    .replace(/[^a-z0-9\s]/g, "")
82	    .replace(/\s+/g, " ")
83	    .trim();
